791	        const MbTileScratch& sc, const MbPartial& part,
792	        const int* __restrict__ tok_ids, const int* __restrict__ tgt_ids,
793	        __nv_bfloat16* sA, __nv_bfloat16* sB, float* red,
794	        float* dBmat_s, float* dCmat_s) {
795	    const int nsamp = nrows / mb::kSeq;
796	
797	    // ── CE bwd + scalar head + final-norm bwd, per sample. dh (last-layer output
798	    //    adjoint) → sc.work_d (zero non-last rows). ──
799	    for (int idx = threadIdx.x; idx < nrows * mb::kD; idx += blockDim.x) sc.work_d[idx] = 0.0f;
800	    __syncthreads();
801	    for (int si = 0; si < nsamp; ++si) {
802	        const int rlast = si * mb::kSeq + (mb::kSeq - 1);
803	        const int gs = g0 / mb::kSeq + si;
804	        float* lg = sc.logits + (int64_t)si * mb::kPHead;
805	        int tgt = tgt_ids[gs];
806	        float lmax = -CUDART_INF_F;
807	        for (int o = threadIdx.x; o < mb::kPHead; o += blockDim.x) lmax = fmaxf(lmax, lg[o]);
808	        lmax = mb_block_max(lmax, red);
809	        float es = 0.0f;
810	        for (int o = threadIdx.x; o < mb::kPHead; o += blockDim.x) es += __expf(lg[o] - lmax);
811	        es = mb_block_sum(es, red);
812	        float inv_es = 1.0f / es;
813	        // dlogits → overwrite lg (scalar head, fp32; NO bf16 — head is not a projection).
814	        for (int o = threadIdx.x; o < mb::kPHead; o += blockDim.x) {
815	            float smo = __expf(lg[o] - lmax) * inv_es;
816	            lg[o] = (smo - ((o == tgt) ? 1.0f : 0.0f)) / (float)B;
817	        }
818	        __syncthreads();
819	        // head: out_b += dl ; out_w[o] += dl * hn  (hn = fn_xhat*norm_w + norm_b).
820	        const float* xh = sc.fn_xhat + (int64_t)rlast * mb::kD;
821	        for (int o = threadIdx.x; o < mb::kPHead; o += blockDim.x) {
822	            float dl = lg[o];
823	            part.out_b[o] += dl;
824	            float* gwrow = part.out_w + (int64_t)o * mb::kD;
825	            #pragma unroll 4
826	            for (int j = 0; j < mb::kD; ++j) gwrow[j] += dl * (xh[j] * w.norm_w[j] + w.norm_b[j]);
827	        }
828	        __syncthreads();
829	        // dhn[j] = Σ_o dl[o]*out_w[o,j] → sc.work_di row 0 (transient; d-wide).
830	        for (int j = threadIdx.x; j < mb::kD; j += blockDim.x) {
831	            float acc = 0.0f;
832	            for (int o = 0; o < mb::kPHead; ++o) acc += lg[o] * w.out_w[(int64_t)o * mb::kD + j];
833	            sc.work_di[j] = acc;   // dhn (reuse work_di[0..d) as transient)
834	        }
835	        __syncthreads();
836	        // final-norm bwd (single row last): norm γ/β → partial; dh[rlast] = LN-dx.
837	        for (int j = threadIdx.x; j < mb::kD; j += blockDim.x) {
838	            float d = sc.work_di[j];
839	            part.norm_b[j] += d; part.norm_w[j] += d * xh[j];
840	        }
841	        __syncthreads();
842	        {
843	            float sda = 0.0f, sdax = 0.0f;
844	            for (int j = threadIdx.x; j < mb::kD; j += blockDim.x) {
845	                float dxhat = sc.work_di[j] * w.norm_w[j]; sda += dxhat; sdax += dxhat * xh[j];
846	            }
847	            sda = mb_block_sum(sda, red); sdax = mb_block_sum(sdax, red);
848	            float iv = sc.fn_inv[rlast];
849	            for (int j = threadIdx.x; j < mb::kD; j += blockDim.x) {
850	                float dxhat = sc.work_di[j] * w.norm_w[j];
851	                sc.work_d[(int64_t)rlast * mb::kD + j] = iv * (dxhat - (sda + xh[j] * sdax) / (float)mb::kD);
852	            }
853	            __syncthreads();
854	        }
855	    }
856	    // sc.work_d now = dh (grad wrt last-layer output [nrows,d], only last pos nonzero).
857	
858	    for (int li = mb::kLayers - 1; li >= 0; --li) {
859	        const MambaWeights::Layer& L = w.layer[li];
860	        // (the residual operand layer_in is read by P2's in_proj dW from acts.X_in[li];
861	        //  the residual ADJOINT path here is the saved dr in sc.work_d.)
862	        // (1) LN bwd (per-sample): dh → dr (sc.work_di2 reused as dr, d-wide);
863	        //     accumulate per-layer norm γ/β into partial.
864	        for (int si = 0; si < nsamp; ++si) {
865	            MambaSampleSmem::LayerAct* a = &sc.act[li][si];
866	            const int r0 = si * mb::kSeq;
867	            mb_layernorm_bwd(sc.work_d + (int64_t)r0 * mb::kD, &a->ln_xhat[0][0], &a->ln_inv[0],
868	                             L.n_w, sc.work_di2 + (int64_t)r0 * mb::kD, part.n_w[li], part.n_b[li], red);
869	        }
870	        // dr lives in sc.work_di2[:, :d]. (2) r = y_out + residual:
871	        //   dy_out = dr ; dx_residual = dr (SAVE dx_residual into sc.work_d — dh free now).
872	        //   dy_out → dY_dyout acts (bf16, out_proj dW operand).
873	        for (int idx = threadIdx.x; idx < nrows * mb::kD; idx += blockDim.x) {
874	            float dr = sc.work_di2[idx];
875	            sc.work_d[idx] = dr;   // dx_residual := dr (saved)
876	            acts.dY_dyout[li][(int64_t)g0 * mb::kD + idx] = __float2bfloat16(dr);
877	        }
878	        __syncthreads();
879	        // (3) out_proj dX: dy_gated = dy_out @ out_w (N=d_inner, K=d). fp32 → sc.work_di.
880	        mbtc_gemm_dx_f32<SG_TUNED_TILE_N>(acts.dY_dyout[li] + (int64_t)g0 * mb::kD, L.out_w,
881	                                          sc.work_di, mb::kDInner, mb::kD, sA, sB);  // dy_gated
882	        __syncthreads();
883	        // Recompute x_main = silu(conv) → sc.xmain (needed by gate bwd + dD + conv-bwd-in
884	        //   is x_main_raw in act cache). conv cache lives in act[li][si].conv.
885	        for (int idx = threadIdx.x; idx < nrows * mb::kDInner; idx += blockDim.x) {
886	            const int si = idx / (mb::kSeq * mb::kDInner);
887	            const int rem = idx % (mb::kSeq * mb::kDInner);
888	            const int t = rem / mb::kDInner, c = rem % mb::kDInner;
889	            sc.xmain[(int64_t)(si * mb::kSeq + t) * mb::kDInner + c] = mb_silu(sc.act[li][si].conv[t][c]);
890	        }
891	        __syncthreads();
892	        // (4-6) gate+skip bwd (elementwise). y_gated = y_skip*silu(z);
893	        //   y_skip = y_scan + x_main*D. sz=silu(z); dy_skip = dy_gated*sz;
894	        //   dsz = dy_gated*y_skip; dz = dsz*silu'(z); dy_scan = dy_skip;
895	        //   dx_main(D-path) = dy_skip*D; dD += Σ dy_skip*x_main.
896	        //   Buffers: dz → sc.work_di2 (dr consumed; reuse, d_inner-wide); dy_scan →
897	        //   act.y_scan (in place); dx_main accumulator(D-path) → sc.work_di
898	        //   (dy_gated consumed). dD → partial (owner channel c).
899	        for (int c = threadIdx.x; c < mb::kDInner; c += blockDim.x) {
900	            float dDc = 0.0f;
901	            #pragma unroll
902	            for (int si = 0; si < nsamp; ++si) {
903	                MambaSampleSmem::LayerAct* a = &sc.act[li][si];
904	                #pragma unroll
905	                for (int t = 0; t < mb::kSeq; ++t) {
906	                    const int r = si * mb::kSeq + t;
907	                    float sz = mb_silu(a->z[t][c]);
908	                    float xm = sc.xmain[(int64_t)r * mb::kDInner + c];
909	                    float yskip = a->y_scan[t][c] + xm * L.D[c];
910	                    float dyg = sc.work_di[(int64_t)r * mb::kDInner + c];   // dy_gated
911	                    float dyskip = dyg * sz;
912	                    float dsz = dyg * yskip;
913	                    sc.work_di2[(int64_t)r * mb::kDInner + c] = dsz * mb_silu_grad(a->z[t][c]);  // dz
914	                    dDc += dyskip * xm;
915	                    a->y_scan[t][c] = dyskip;                               // dy_scan (in place)
916	                    sc.work_di[(int64_t)r * mb::kDInner + c] = dyskip * L.D[c];  // dx_main_D (overwrite dy_gated)
917	                }
918	            }
919	            part.D[li][c] += dDc;
920	        }
921	        __syncthreads();
922	        // (7) selective scan bwd (per-sample scalar). x_main = sc.xmain (untouched).
923	        //   dy_scan = act.y_scan. Outputs: dx_main_scan → act.z (in place; z fwd
924	        //   consumed as dz=work_di2); ddt_pre → act.dt_pre (in place); dB/dC →
925	        //   smem dBmat_s/dCmat_s (zeroed per sample), consumed into sc.dbc; dA_log
926	        //   → partial. Then dx_main = D-path(work_di) + scan-path(act.z) → work_di.
927	        for (int si = 0; si < nsamp; ++si) {
928	            MambaSampleSmem::LayerAct* a = &sc.act[li][si];
929	            const int r0 = si * mb::kSeq;
930	            for (int idx = threadIdx.x; idx < mb::kSeq * mb::kState; idx += blockDim.x) {
931	                dBmat_s[idx] = 0.0f; dCmat_s[idx] = 0.0f;
932	            }
933	            __syncthreads();
934	#if !SG_MBTC_BYPASS_SCAN
935	            mb_scan_bwd(L.A_log, sc.xmain + (int64_t)r0 * mb::kDInner, a, &a->y_scan[0][0],
936	                        &a->z[0][0],        // dx_main_scan SET → act.z
937	                        &a->dt_pre[0][0],   // ddt_pre SET → act.dt_pre (in place, safe per channel)
938	                        dBmat_s, dCmat_s, part.A_log[li], red);
939	#else
940	            for (int idx = threadIdx.x; idx < mb::kSeq * mb::kDInner; idx += blockDim.x) {
941	                const int t = idx / mb::kDInner, c = idx % mb::kDInner;
942	                a->z[t][c] = 0.0f; a->dt_pre[t][c] = 0.0f;   // bypass: zero scan-bwd outputs
943	            }
944	            __syncthreads();
945	#endif
946	            // ddt_pre → dY_ddtpre acts (bf16, dt_proj dW operand) + assemble dx_dbc's
947	            //   B/C halves into sc.dbc (ddt_raw filled after dt_proj dX). dt_raw also
948	            //   needed for dt_proj dW (X operand) — already stored bf16 in acts.X_dtraw.
949	            for (int idx = threadIdx.x; idx < mb::kSeq * mb::kDInner; idx += blockDim.x) {
950	                const int t = idx / mb::kDInner, o = idx % mb::kDInner;
951	                acts.dY_ddtpre[li][(int64_t)(g0 + r0 + t) * mb::kDInner + o] = __float2bfloat16(a->dt_pre[t][o]);
952	            }
953	            // dB/dC → sc.dbc[:, dt_rank..] for this sample's rows.
954	            for (int idx = threadIdx.x; idx < mb::kSeq * mb::kState; idx += blockDim.x) {
955	                const int t = idx / mb::kState, k = idx % mb::kState;
956	                const int r = r0 + t;
957	                sc.dbc[(int64_t)r * mb::kDbc + mb::kDtRank + k] = dBmat_s[t * mb::kState + k];
958	                sc.dbc[(int64_t)r * mb::kDbc + mb::kDtRank + mb::kState + k] = dCmat_s[t * mb::kState + k];
959	            }
960	            __syncthreads();
961	        }
962	        // dx_main = D-path (work_di) + scan-path (act.z) → work_di2 (dz consumed:
963	        //   dz was needed for the in_proj dxz — STILL NEEDED at step 12! So do NOT
964	        //   clobber work_di2 yet. Put dx_main into work_di in place: work_di holds
965	        //   dx_main_D; add scan-path act.z).
966	        for (int idx = threadIdx.x; idx < nrows * mb::kDInner; idx += blockDim.x) {
967	            const int si = idx / (mb::kSeq * mb::kDInner);
968	            const int rem = idx % (mb::kSeq * mb::kDInner);
969	            const int t = rem / mb::kDInner, c = rem % mb::kDInner;
970	            sc.work_di[idx] += sc.act[li][si].z[t][c];   // dx_main = D-path + scan-path (in work_di)
971	        }
972	        __syncthreads();
973	        // (8) dt_proj dX: ddt_raw = ddt_pre @ dt_proj_w (N=dt_rank=8, K=d_inner).
974	        //   fp32 → sc.dbc[:, :dt_rank] (the ddt_raw half of dx_dbc). dt_proj dW
975	        //   (ddt_pre^T@dt_raw) + bias (Σ ddt_pre) are P2 (both operands in acts).
976	        {
977	            auto srcA = [&] (int m, int k) -> __nv_bfloat16 {
978	                return k < mb::kDInner ? acts.dY_ddtpre[li][(int64_t)(g0 + m) * mb::kDInner + k] : __float2bfloat16(0.f); };
979	            auto srcB = [&] (int n, int k) -> __nv_bfloat16 {
980	                return (n < mb::kDtRank && k < mb::kDInner) ? __float2bfloat16(L.dt_proj_w[(int64_t)k * mb::kDtRank + n]) : __float2bfloat16(0.f); };
981	            auto out = [&] (int m, int n, float v) {
982	                if (n < mb::kDtRank) sc.dbc[(int64_t)m * mb::kDbc + n] = v; };   // ddt_raw → dbc[:, :dt_rank]
983	            tc_gemm_block_unpipelined<SG_TUNED_TILE_N, /*MaxAtomsM=*/kAtomsM>(
984	                0, kAtomsM, mb::kDtRank, kceil16(mb::kDInner), srcA, srcB, out, sA, sB);
985	        }
986	        __syncthreads();
987	        // dx_dbc = cat[ddt_raw, dB, dC] now complete in sc.dbc. → dY_dxdbc acts (bf16,
988	        //   x_proj dW operand). x_proj dW (dx_dbc^T@x_main) is P2 (both in acts).
989	        for (int idx = threadIdx.x; idx < nrows * mb::kDbc; idx += blockDim.x) {
990	            const int r = idx / mb::kDbc, o = idx % mb::kDbc;
991	            acts.dY_dxdbc[li][(int64_t)(g0 + r) * mb::kDbc + o] = __float2bfloat16(sc.dbc[(int64_t)r * mb::kDbc + o]);
992	        }
993	        __syncthreads();
994	        // (9) x_proj dX: dx_main(x_proj path) = dx_dbc @ x_proj_w (N=d_inner, K=dbc=40
995	        //   PADDED→48). fp32 → sc.work_di2? No — work_di2 holds dz (needed step 12).
996	        //   Use sc.xmain (x_main fwd consumed: scan bwd done, gate bwd done, dD done —
997	        //   x_main no longer needed). dx_main(x_proj) → sc.xmain; then ADD to the
998	        //   dx_main accumulator (work_di).
999	        mbtc_gemm_dx_f32<SG_TUNED_TILE_N>(acts.dY_dxdbc[li] + (int64_t)g0 * mb::kDbc, L.x_proj_w,
1000	                                          sc.xmain, mb::kDInner, mb::kDbc, sA, sB);  // dx_main_xproj
1001	        __syncthreads();
1002	        for (int idx = threadIdx.x; idx < nrows * mb::kDInner; idx += blockDim.x)
1003	            sc.work_di[idx] += sc.xmain[idx];   // dx_main complete (work_di)
1004	        __syncthreads();
1005	        // (10-11) dconv = dx_main * silu'(conv) → sc.xmain (x_main consumed). conv bwd
1006	        //   (per-sample scalar): conv_w/conv_b → partial; dx_main_raw → sc.work_di
1007	        //   (dx_main consumed; reuse, d_inner-wide).
1008	        for (int idx = threadIdx.x; idx < nrows * mb::kDInner; idx += blockDim.x) {
1009	            const int si = idx / (mb::kSeq * mb::kDInner);
1010	            const int rem = idx % (mb::kSeq * mb::kDInner);
1011	            const int t = rem / mb::kDInner, c = rem % mb::kDInner;
1012	            sc.xmain[idx] = sc.work_di[idx] * mb_silu_grad(sc.act[li][si].conv[t][c]);   // dconv
1013	        }
1014	        __syncthreads();
1015	        for (int si = 0; si < nsamp; ++si) {
1016	            MambaSampleSmem::LayerAct* a = &sc.act[li][si];
1017	            const int r0 = si * mb::kSeq;
1018	            mb_conv1d_bwd(sc.xmain + (int64_t)r0 * mb::kDInner, &a->x_main_raw[0][0], L.conv_w,
1019	                          part.conv_w[li], part.conv_b[li], sc.work_di + (int64_t)r0 * mb::kDInner);  // dx_main_raw
1020	        }
1021	        // (12) dxz = cat[dx_main_raw (work_di), dz (work_di2)] → dY_dxz acts (bf16,
1022	        //   in_proj dW operand, [T, 2*d_inner]). in_proj dW (dxz^T@layer_in) is P2.
1023	        for (int idx = threadIdx.x; idx < nrows * mb::kDInner; idx += blockDim.x) {
1024	            const int r = idx / mb::kDInner, c = idx % mb::kDInner;
1025	            acts.dY_dxz[li][(int64_t)(g0 + r) * 2 * mb::kDInner + c] = __float2bfloat16(sc.work_di[idx]);              // dx_main_raw half
1026	            acts.dY_dxz[li][(int64_t)(g0 + r) * 2 * mb::kDInner + mb::kDInner + c] = __float2bfloat16(sc.work_di2[idx]); // dz half
1027	        }
1028	        __syncthreads();
1029	        // (13) in_proj dX: dx_inproj = dxz @ in_w (N=d, K=2*d_inner). fp32 → sc.work_di
1030	        //   (dx_main_raw consumed). dh = dx_inproj + dx_residual(sc.work_d) → sc.work_d
1031	        //   (the previous layer's output adjoint, or the embedding grad for li=0).
1032	        mbtc_gemm_dx_f32<SG_TUNED_TILE_N>(acts.dY_dxz[li] + (int64_t)g0 * 2 * mb::kDInner, L.in_w,
1033	                                          sc.work_di, mb::kD, 2 * mb::kDInner, sA, sB);  // dx_inproj [nrows,d]
1034	        __syncthreads();
1035	        for (int idx = threadIdx.x; idx < nrows * mb::kD; idx += blockDim.x)
1036	            sc.work_d[idx] += sc.work_di[idx];   // dh = residual + in_proj path
1037	        __syncthreads();
1038	    }
1039	
1040	    // ── embedding bwd: dh = grad wrt h0 [nrows,d] (sc.work_d). → dh0 acts (bf16);
1041	    //    tok/pos owner-scan (P2) reads dh0. ──
1042	    for (int idx = threadIdx.x; idx < nrows * mb::kD; idx += blockDim.x)
1043	        acts.dh0[(int64_t)g0 * mb::kD + idx] = __float2bfloat16(sc.work_d[idx]);
1044	    __syncthreads();
1045	}
1046	
1047	// ════════════════════════════════════════════════════════════════════════
1048	//  P2 — OUTPUT-STATIONARY dW (the 4 projections × kLayers = 8 weight matrices,
1049	//  dW = dYᵀ @ X, K=T). Each split into 64×N output tiles; tile_id % nCTA owns
1050	//  each, contracting the FULL T (ascending-t, no atomics, no partials) via the
1051	//  validated dW orientation (both operands transposed-staged, MaxAtomsM=1).
1052	//  Writes into `grad`. The ONLY GEMM bias is dt_proj.bias = Σ_T ddt_pre.
1053	//
1054	//  The 8 weights, in named_parameters() tensor-index order:
1055	//    L0: in_w=4, x_proj_w=7, dt_proj_w=8, out_w=10
1056	//    L1: in_w=15, x_proj_w=18, dt_proj_w=19, out_w=21
1057	//  with (dY, X) acts and Nout/Kin per the forward projection.
1058	// ════════════════════════════════════════════════════════════════════════
1059	// (still in namespace mbtc — opened above)
1060	
1061	struct MbDwSpec {
1062	    const __nv_bfloat16* dY;   // [T, Nout]
1063	    const __nv_bfloat16* X;    // [T, Kin]
1064	    int Nout; int Kin; int T;
1065	    int grad_off;
1066	    bool has_bias;             // only dt_proj
1067	    const __nv_bfloat16* dY_bias;
1068	    int bias_off;
1069	};
1070	
1071	// Build the 8 specs (cheap; all CTAs). T = B*kSeq.
1072	__device__ __forceinline__ void mbtc_build_dw_specs(
1073	        const MbActs& acts, int T, MbDwSpec spec[8]) {
1074	    // per-layer tensor indices (and dt bias idx). L0 base=2 (tok=0,pos=1), 11/layer.
1075	    for (int li = 0; li < mb::kLayers; ++li) {
1076	        const int base = 2 + li * 11;
1077	        const int in_w = base + 2, xp_w = base + 5, dt_w = base + 6, dt_b = base + 7, out_w = base + 8;
1078	        MbDwSpec& s_in = spec[li * 4 + 0];
1079	        s_in.dY = acts.dY_dxz[li];   s_in.X = acts.X_in[li];
1080	        s_in.Nout = 2 * mb::kDInner; s_in.Kin = mb::kD; s_in.T = T;
1081	        s_in.grad_off = kMambaOffsets[in_w]; s_in.has_bias = false;
1082	        MbDwSpec& s_xp = spec[li * 4 + 1];
1083	        s_xp.dY = acts.dY_dxdbc[li]; s_xp.X = acts.X_xmain[li];
1084	        s_xp.Nout = mb::kDbc; s_xp.Kin = mb::kDInner; s_xp.T = T;
1085	        s_xp.grad_off = kMambaOffsets[xp_w]; s_xp.has_bias = false;
1086	        MbDwSpec& s_dt = spec[li * 4 + 2];
1087	        s_dt.dY = acts.dY_ddtpre[li]; s_dt.X = acts.X_dtraw[li];
1088	        s_dt.Nout = mb::kDInner; s_dt.Kin = mb::kDtRank; s_dt.T = T;
1089	        s_dt.grad_off = kMambaOffsets[dt_w]; s_dt.has_bias = true;
1090	        s_dt.dY_bias = acts.dY_ddtpre[li]; s_dt.bias_off = kMambaOffsets[dt_b];
1091	        MbDwSpec& s_out = spec[li * 4 + 3];
1092	        s_out.dY = acts.dY_dyout[li]; s_out.X = acts.X_ygated[li];
1093	        s_out.Nout = mb::kD; s_out.Kin = mb::kDInner; s_out.T = T;
1094	        s_out.grad_off = kMambaOffsets[out_w]; s_out.has_bias = false;
1095	    }
