1098	template <int N>
1099	__device__ __forceinline__ int mbtc_dw_total_tiles(const MbDwSpec spec[8]) {
1100	    int n = 0;
1101	    for (int s = 0; s < 8; ++s)
1102	        n += ((spec[s].Nout + 63) / 64) * ((spec[s].Kin + N - 1) / N);
1103	    return n;
