1106	// Run ONE global dW tile gt (if owned): dW = dYᵀ @ X, contract K=T. Both operands
1107	// transposed-staged. K=T is a multiple of 16 (host enforces B%16==0 → T=B·8).
1108	template <int N>
1109	__device__ __forceinline__ void mbtc_dw_run_tile(
1110	        const MbDwSpec spec[8], int gt, float* __restrict__ grad,
1111	        __nv_bfloat16* sA, __nv_bfloat16* sB) {
1112	    int acc = 0, s = 0, m_atom = 0, n_tile = 0;
1113	    for (s = 0; s < 8; ++s) {
1114	        const int ma = (spec[s].Nout + 63) / 64;
1115	        const int nt = (spec[s].Kin + N - 1) / N;
1116	        if (gt < acc + ma * nt) { int loc = gt - acc; m_atom = loc / nt; n_tile = loc % nt; break; }
1117	        acc += ma * nt;
1118	    }
1119	    const MbDwSpec& sp = spec[s];
1120	    const int mbase = m_atom * 64;
1121	    const int n0 = n_tile * N;
1122	    const int n_real = (sp.Kin - n0) < N ? (sp.Kin - n0) : N;
1123	    const int k_steps = sp.T / wgs::kWgmmaAtomK;
1124	    const int Nout = sp.Nout, Kin = sp.Kin;
1125	    const __nv_bfloat16* dY = sp.dY; const __nv_bfloat16* X = sp.X;
1126	    // A[m=out, k=t] = dY[t,out] (transposed); B[n=in, k=t] = X[t,in] (transposed).
1127	    auto srcA = [&] (int m, int k) -> __nv_bfloat16 {
1128	        return m < Nout ? dY[(int64_t)k * Nout + m] : __float2bfloat16(0.f); };
1129	    auto srcB = [&] (int n, int k) -> __nv_bfloat16 {
1130	        int nn = n0 + n; return nn < Kin ? X[(int64_t)k * Kin + nn] : __float2bfloat16(0.f); };
1131	    auto out  = [&] (int m, int n, float v) {
1132	        if (m < Nout) grad[sp.grad_off + (int64_t)m * Kin + n0 + n] = v; };
1133	    tc_gemm_block_unpipelined<N, /*MaxAtomsM=*/1>(
1134	        mbase, /*m_atoms=*/1, n_real, k_steps, srcA, srcB, out, sA, sB);
1135	}
