1137	// ════════════════════════════════════════════════════════════════════════
1138	//  SPLIT-K dW (the "multi-CTA tiling" fix for the ~73% idle SMs in P2). The 8
1139	//  projection dW = dYᵀ@X contract K=T (=B·kSeq, 131072 at B=16384) but yield
1140	//  only ~36 output tiles → with 132 SMs, ~96 idle for ALL of P2 (PROFILED: the
1141	//  K-loop is occupancy-bound, NOT latency-bound — a K-loop double-buffer moved
1142	//  the dW phase 0%). Split-K turns each output tile into G work items (one per
1143	//  K-chunk), so the work-steal fans (n_dw·G) items over the grid → the idle SMs
1144	//  do real work. Each CTA computes a PARTIAL over its K-chunk into a per-
1145	//  (tile,chunk) scratch slot; a grid barrier; then a DETERMINISTIC ascending-
1146	//  chunk reduce sums the G partials into grad — no float atomics, fixed order,
1147	//  so A/A/A bit-determinism + the 0.08 parity hold (each partial is the SAME
1148	//  ascending-k fp32 wgmma accumulate; Σ_chunk partial == the full-K sum
1149	//  reassociated into G fp32 blocks; the tol absorbs the reassociation). G==1
1150	//  routes to the single-CTA mbtc_dw_run_tile above (no scratch, byte-identical).
1151	//
1152	//  Partial scratch layout (flat, host-sized): slot (gt, kc) at
1153	//    dw_part[((int64_t)gt*G + kc) * (64*kMbMaxTileN) + row*kMbMaxTileN + col].
1154	//  The reduce reads [0,Nrow)×[0,n_real) and scatters to grad[grad_off +
1155	//  (mbase+row)*Kin + n0+col]. Biases (dt_proj only) stay in mbtc_dw_biases.
1156	// ════════════════════════════════════════════════════════════════════════
1157	constexpr int kMbMaxTileN = SG_TUNED_TILE_N;                      // widest dW N-tile
1158	constexpr int kMbDwTileFloats = wgs::kWgmmaAtomM * kMbMaxTileN;   // 64*N per (gt,kc) slot
1159	
1160	// COMPILE-TIME max #dW output tiles (the 8 projection dW have fixed Nout/Kin —
1161	// mamba dims are compile-time — so n_dw is a constant; mbtc_dw_total_tiles
1162	// returns this at runtime, but the host needs it to size the split-K scratch).
1163	//   per layer: in(512×128), x_proj(40×256), dt_proj(256×8), out(128×256), N=kMbMaxTileN
1164	constexpr int kMbDwTilesPerLayer =
1165	      ((2*mb::kDInner + 63)/64) * ((mb::kD + kMbMaxTileN - 1)/kMbMaxTileN)      // in_proj
1166	    + ((mb::kDbc + 63)/64)      * ((mb::kDInner + kMbMaxTileN - 1)/kMbMaxTileN) // x_proj
1167	    + ((mb::kDInner + 63)/64)   * ((mb::kDtRank + kMbMaxTileN - 1)/kMbMaxTileN) // dt_proj
1168	    + ((mb::kD + 63)/64)        * ((mb::kDInner + kMbMaxTileN - 1)/kMbMaxTileN);// out_proj
1169	constexpr int kMbDwMaxTiles = mb::kLayers * kMbDwTilesPerLayer;
1170	
1171	// Split-K dW partial-scratch float count (host carves it from the workspace tail):
1172	// kMbDwMaxTiles tiles × G chunks × one 64×N slot each.
1173	__host__ __device__ __forceinline__ int64_t mb_dw_part_floats(int G) {
1174	    return (int64_t)kMbDwMaxTiles * G * kMbDwTileFloats;
1175	}
