1177	// Decode global dW tile index gt → (spec index s, m_atom, n_tile). Shared by the
1178	// partial pass + the reduce so the (gt → tile geometry) map is single-source.
1179	template <int N>
1180	__device__ __forceinline__ void mbtc_dw_decode(
1181	        const MbDwSpec spec[8], int gt, int& s, int& m_atom, int& n_tile) {
1182	    int acc = 0;
1183	    for (s = 0; s < 8; ++s) {
1184	        const int ma = (spec[s].Nout + 63) / 64;
1185	        const int nt = (spec[s].Kin + N - 1) / N;
1186	        if (gt < acc + ma * nt) { int loc = gt - acc; m_atom = loc / nt; n_tile = loc % nt; return; }
1187	        acc += ma * nt;
1188	    }
1189	    s = 7; m_atom = 0; n_tile = 0;   // unreachable (gt < n_dw); keep defined
1190	}
