1192	// PARTIAL dW for global tile gt over K-chunk kc of G → dw_part. K-chunk =
1193	// [kc*kc_steps, (kc+1)*kc_steps) in 16-wide k-atoms; the launcher chooses
1194	// G | (T/16) so chunks are equal + 16-aligned. Fresh ScaleD=0 per chunk → a
1195	// true partial. Writes the full 64×N tile contiguously into the (gt,kc) slot.
1196	template <int N>
1197	__device__ __forceinline__ void mbtc_dw_run_tile_splitk(
1198	        const MbDwSpec spec[8], int gt, int kc, int G, float* __restrict__ dw_part,
1199	        __nv_bfloat16* sA, __nv_bfloat16* sB) {
1200	    int s, m_atom, n_tile;
1201	    mbtc_dw_decode<N>(spec, gt, s, m_atom, n_tile);
1202	    const MbDwSpec& sp = spec[s];
1203	    const int mbase = m_atom * 64;
1204	    const int n0 = n_tile * N;
1205	    const int kc_steps = (sp.T / wgs::kWgmmaAtomK) / G;   // equal chunks (G | k_steps_total)
1206	    const int k0 = kc * kc_steps;
1207	    const int Nout = sp.Nout, Kin = sp.Kin;
1208	    const __nv_bfloat16* dY = sp.dY; const __nv_bfloat16* X = sp.X;
1209	    // srcA/srcB offset the K axis by k0*16 (the chunk's first token); k local to chunk.
1210	    auto srcA = [&] (int m, int k) -> __nv_bfloat16 {
1211	        return m < Nout ? dY[(int64_t)(k0 * wgs::kWgmmaAtomK + k) * Nout + m] : __float2bfloat16(0.f); };
1212	    auto srcB = [&] (int n, int k) -> __nv_bfloat16 {
1213	        int nn = n0 + n; return nn < Kin ? X[(int64_t)(k0 * wgs::kWgmmaAtomK + k) * Kin + nn] : __float2bfloat16(0.f); };
1214	    float* slot = dw_part + ((int64_t)gt * G + kc) * kMbDwTileFloats;
1215	    // The GEMM calls out(mbase+row, col, v) with GLOBAL m = mbase+row (srcA reads
1216	    // dY[m·Nout] so m MUST stay global), but the slot holds only THIS atom's 64
1217	    // LOCAL rows → index by (m - mbase). A `m < 64` guard would NEVER fire for
1218	    // m_atom>=1 (mbase>=64) → that atom's slot stays UNWRITTEN and the reduce sums
1219	    // garbage (the rel~1.0 dW bug). Local-row indexing fills every slot fully.
1220	    auto out  = [&] (int m, int n, float v) {
1221	        const int lr = m - mbase;
1222	        if (lr >= 0 && lr < 64 && n < N) slot[(int64_t)lr * N + n] = v; };
1223	    tc_gemm_block_unpipelined<N, /*MaxAtomsM=*/1>(
1224	        mbase, /*m_atoms=*/1, /*n_real=*/N, kc_steps, srcA, srcB, out, sA, sB);
1225	}
