1227	// Deterministic reduce: output tile gt (% nCTA) sums its G chunk-partials in
1228	// ASCENDING kc and scatters to grad. Same (gt → geometry) decode as the partial.
1229	template <int N>
1230	__device__ __forceinline__ void mbtc_dw_reduce_splitk(
1231	        const MbDwSpec spec[8], int n_dw, int G, const float* __restrict__ dw_part,
1232	        float* __restrict__ grad, int cta, int nCTA) {
1233	    for (int gt = cta; gt < n_dw; gt += nCTA) {
1234	        int s, m_atom, n_tile;
1235	        mbtc_dw_decode<N>(spec, gt, s, m_atom, n_tile);
1236	        const MbDwSpec& sp = spec[s];
1237	        const int mbase = m_atom * 64;
1238	        const int n0 = n_tile * N;
1239	        const int n_real = (sp.Kin - n0) < N ? (sp.Kin - n0) : N;
1240	        const int Nrow = (sp.Nout - mbase) < 64 ? (sp.Nout - mbase) : 64;
1241	        const int64_t base = (int64_t)gt * G * kMbDwTileFloats;
1242	        for (int idx = threadIdx.x; idx < Nrow * n_real; idx += blockDim.x) {
1243	            const int row = idx / n_real, col = idx % n_real;
1244	            float accv = 0.0f;
1245	            for (int kc = 0; kc < G; ++kc)            // ascending chunk → deterministic
1246	                accv += dw_part[base + (int64_t)kc * kMbDwTileFloats + (int64_t)row * N + col];
1247	            grad[sp.grad_off + (int64_t)(mbase + row) * sp.Kin + n0 + col] = accv;
1248	        }
1249	    }
1250	}
