1252	// dt_proj.bias db = Σ_T ddt_pre (the ONLY GEMM bias). The reduction over T is
1253	// O(T=B·kSeq) PER output element; striping it across ALL nCTA CTAs (not letting
1254	// every CTA redundantly recompute the full O(T) sum for every output and race-write
1255	// the same grad slot — the measured ~19%-of-wall uniform straggler: mean≈max across
1256	// CTAs because ALL 132 did the SAME full work) cuts that ~nCTA-fold. We enumerate a
1257	// GLOBAL bias-output index over the (bias-carrying spec s, output o) space and
1258	// round-robin it by (cta·blockDim + tid) so each output is summed by exactly ONE
1259	// thread on ONE CTA — single owner, deterministic, no race, no redundancy.
1260	__device__ __forceinline__ void mbtc_dw_biases(
1261	        const MbDwSpec spec[8], float* __restrict__ grad, int cta, int nCTA) {
1262	    int total_bias = 0;
1263	    #pragma unroll
1264	    for (int s = 0; s < 8; ++s) total_bias += spec[s].has_bias ? spec[s].Nout : 0;
1265	    const int64_t base_thread = (int64_t)cta * blockDim.x + threadIdx.x;
1266	    const int64_t stride = (int64_t)nCTA * blockDim.x;
1267	    for (int64_t gi = base_thread; gi < total_bias; gi += stride) {
1268	        int s = 0, o = (int)gi;
1269	        #pragma unroll
1270	        for (int ss = 0; ss < 8; ++ss) {
1271	            if (!spec[ss].has_bias) continue;
1272	            if (o < spec[ss].Nout) { s = ss; break; }
1273	            o -= spec[ss].Nout;
1274	        }
1275	        const MbDwSpec& sp = spec[s];
1276	        float accv = 0.0f;
1277	        for (int k = 0; k < sp.T; ++k) accv += __bfloat162float(sp.dY_bias[(int64_t)k * sp.Nout + o]);
1278	        grad[sp.bias_off + o] = accv;
1279	    }
1280	}
