1282	// ════════════════════════════════════════════════════════════════════════
1283	//  P2 — NON-GEMM grad reduce (A_log, D, conv_w/b, n_w/b per layer + head
1284	//  norm_w/b, out_w/b). Each was accumulated tile-local into the per-CTA partial
1285	//  [kPartElems]; sum across CTAs in ASCENDING CTA index (deterministic) into the
1286	//  named_parameters() slots of grad. `part_base` = start of [nCTA × kPartElems].
1287	//  Work split round-robin over the kPartElems by FLAT element (each element c is
1288	//  owned by cta = (global_flat_index / chunk)?) — simplest deterministic split:
1289	//  CTA strides the kPartElems by tensor (round-robin tensors), summing each
1290	//  tensor's elements across CTAs. We enumerate the (tensor-index, partial-slot,
1291	//  numel) triples and round-robin them by CTA.
1292	// ════════════════════════════════════════════════════════════════════════
1293	// Number of partial tensors to reduce: 6/layer + 4 head.
1294	constexpr int kNumPartTensors = mb::kLayers * 6 + 4;
1295	
1296	// Fill the (grad tensor index, partial-offset-in-CTA-slab, numel) for slot v.
1297	__device__ __forceinline__ void mbtc_part_slot(
1298	        int v, int& grad_idx, int64_t& part_off, int& numel) {
1299	    // per-layer order: A_log, D, conv_w, conv_b, n_w, n_b (6); head: norm_w,norm_b,out_w,out_b.
1300	    const int kLayerNumels[6] = {
1301	        mb::kDInner * mb::kState, mb::kDInner, mb::kDInner * mb::kConvK, mb::kDInner, mb::kD, mb::kD };
1302	    if (v < mb::kLayers * 6) {
1303	        const int li = v / 6, kind = v % 6;
1304	        const int base = 2 + li * 11;
1305	        const int tidx[6] = { base + 0, base + 1, base + 3, base + 4, base + 9, base + 10 };  // A_log,D,conv_w,conv_b,n_w,n_b
1306	        grad_idx = tidx[kind];
1307	        // partial offset within a CTA slab:
1308	        int64_t off = (int64_t)li * kPartPerLayer;
1309	        for (int k = 0; k < kind; ++k) off += kLayerNumels[k];
1310	        part_off = off; numel = kLayerNumels[kind];
1311	    } else {
1312	        const int h = v - mb::kLayers * 6;   // 0..3: norm_w,norm_b,out_w,out_b
1313	        const int htidx[4] = { 2 + mb::kLayers * 11 + 0, 2 + mb::kLayers * 11 + 1,
1314	                               2 + mb::kLayers * 11 + 2, 2 + mb::kLayers * 11 + 3 };
1315	        const int hnum[4] = { mb::kD, mb::kD, mb::kPHead * mb::kD, mb::kPHead };
1316	        grad_idx = htidx[h];
1317	        int64_t off = (int64_t)mb::kLayers * kPartPerLayer;
1318	        for (int k = 0; k < h; ++k) off += hnum[k];
1319	        part_off = off; numel = hnum[h];
1320	    }
1321	}
