1323	// Map a flat slab index e → (grad base offset, local index) by re-deriving the
1324	// segment via mbtc_part_slot (16 tensors; cheap, register-only — NO __shared__,
1325	// which would collide with the kernel's MbTcSmem staging arena). The `seg` cursor
1326	// is carried across the grid-stride loop so consecutive e only re-scan at tensor
1327	// boundaries (warp-coherent for long runs).
1328	__device__ __forceinline__ void mbtc_part_flat_map(
1329	        int64_t e, int& seg, int64_t& gdst) {
1330	    int gidx, numel; int64_t poff;
1331	    mbtc_part_slot(seg, gidx, poff, numel);
1332	    // advance forward (e is monotonically increasing within a thread's stride run);
1333	    // if e fell before the cached segment (first iter / stride wrap), reset to 0.
1334	    if (e < poff) { seg = 0; mbtc_part_slot(seg, gidx, poff, numel); }
1335	    while (e >= poff + numel) { ++seg; mbtc_part_slot(seg, gidx, poff, numel); }
1336	    gdst = kMambaOffsets[gidx] + (e - poff);
1337	}
1338	
1339	// FLAT-PARALLEL cross-CTA reduce: stripe the kPartElems flat slab elements across
1340	// ALL nCTA CTAs × blockDim threads (not the old by-tensor split that left only
1341	// kNumPartTensors=16 of 132 CTAs working while 116 idled at the B2 barrier — the
1342	// measured ~19%-of-wall straggler). Each flat element e is summed across the nCTA
1343	// per-CTA partials in ASCENDING c (deterministic, unchanged) and scattered to its
1344	// grad tensor. Element ownership is a fixed function of e, so the reduce stays
1345	// bit-identical across runs (gate-2 A/A/A) — same addends, same ascending-c order.
1346	__device__ __forceinline__ void mbtc_partial_reduce(
1347	        const float* __restrict__ part_base, float* __restrict__ grad,
1348	        int nCTA, int cta) {
1349	    const int64_t stride = (int64_t)nCTA * blockDim.x;
1350	    int seg = 0;
1351	    for (int64_t e = (int64_t)cta * blockDim.x + threadIdx.x; e < kPartElems; e += stride) {
1352	        int64_t gdst;
1353	        mbtc_part_flat_map(e, seg, gdst);
1354	        float accv = 0.0f;
1355	        for (int c = 0; c < nCTA; ++c)
1356	            accv += part_base[(int64_t)c * kPartElems + e];
1357	        grad[gdst] = accv;
1358	    }
1359	}
