1361	// ════════════════════════════════════════════════════════════════════════
1362	//  P2 — EMBEDDING owner-scan (tok/pos). dh0 [T,d] (bf16) holds grad wrt h0.
1363	//    tok grad row r (token id) → owner CTA (r % nCTA), scans ALL T tokens
1364	//    ascending-t accumulating dh0[t,:] for ids == r. pos row p → owner, sums
1365	//    dh0[t,:] over t with (t%S)==p. Fixed t-order + single owner → deterministic.
1366	// ════════════════════════════════════════════════════════════════════════
1367	__device__ __forceinline__ void mbtc_embed_owner_scan(
1368	        const MbActs& acts, const int* __restrict__ tok_ids, int T,
1369	        float* __restrict__ grad, int cta, int nCTA) {
1370	    const int tok_off = kMambaOffsets[0];
1371	    const int pos_off = kMambaOffsets[1];
1372	    for (int r = cta; r < mb::kVocab; r += nCTA) {
1373	        for (int j = threadIdx.x; j < mb::kD; j += blockDim.x) {
1374	            float accv = 0.0f;
1375	            for (int t = 0; t < T; ++t)
1376	                if (tok_ids[t] == r) accv += __bfloat162float(acts.dh0[(int64_t)t * mb::kD + j]);
1377	            grad[tok_off + (int64_t)r * mb::kD + j] = accv;
1378	        }
1379	    }
1380	    for (int p = cta; p < mb::kSeq; p += nCTA) {
1381	        for (int j = threadIdx.x; j < mb::kD; j += blockDim.x) {
1382	            float accv = 0.0f;
1383	            for (int t = 0; t < T; ++t)
1384	                if ((t % mb::kSeq) == p) accv += __bfloat162float(acts.dh0[(int64_t)t * mb::kD + j]);
1385	            grad[pos_off + (int64_t)p * mb::kD + j] = accv;
1386	        }
1387	    }
