```
float mb_block_sum(float v, float* red) {
    for (o=16..1) v += __shfl_down_sync(full, v, o);   // warp reduce → lane 0 has warp sum
    if (lane==0) red[warp] = v;                          // write 8 warp sums (256 threads = 8 warps)
