    if (warp==0) { p = (lane<nwarp)?red[lane]:0; for(o=16..1) p+=shfl; if(lane==0) red[0]=p; }
    __syncthreads();
    float r = red[0]; __syncthreads(); return r;
}
```

This is deterministic. The order is fixed. Let me check the background result.

